17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.regex.Pattern;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
36	import org.springframework.samples.petclinic.rest.api.OwnersApi;
37	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
38	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.PetDto;
40	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
43	import org.springframework.samples.petclinic.service.ClinicService;
44	import org.springframework.security.access.prepost.PreAuthorize;
45	import org.springframework.web.bind.annotation.CrossOrigin;
46	import org.springframework.web.bind.annotation.RequestMapping;
47	import org.springframework.web.bind.annotation.RestController;
48	import org.springframework.web.util.UriComponentsBuilder;
49	
50	import jakarta.transaction.Transactional;
51	
52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    public OwnerRestControllerV1(ClinicService clinicService,
70	                                 OwnerMapper ownerMapper,
71	                                 PetMapper petMapper,
72	                                 VisitMapper visitMapper) {
73	        this.clinicService = clinicService;
74	        this.ownerMapper = ownerMapper;
75	        this.petMapper = petMapper;
76	        this.visitMapper = visitMapper;
77	    }
78	
79	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
80	    @Override
81	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
82	        Collection<Owner> owners;
83	        if (lastName != null) {
84	            owners = this.clinicService.findOwnerByLastName(lastName);
85	        } else {
86	            owners = this.clinicService.findAllOwners();
87	        }
88	        if (owners.isEmpty()) {
89	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
90	        }
91	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
92	    }
93	
94	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
95	    @Override
96	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
97	        Owner owner = this.clinicService.findOwnerById(ownerId);
98	        if (owner == null) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        List<String> missingFields = new ArrayList<>();
108	        if (isBlank(ownerFieldsDto.getFirstName())) {
109	            missingFields.add("firstName");
110	        }
111	        if (isBlank(ownerFieldsDto.getLastName())) {
112	            missingFields.add("lastName");
113	        }
114	        if (isBlank(ownerFieldsDto.getAddress())) {
115	            missingFields.add("address");
116	        }
117	        if (isBlank(ownerFieldsDto.getCity())) {
118	            missingFields.add("city");
119	        }
120	        if (isBlank(ownerFieldsDto.getTelephone())) {
121	            missingFields.add("telephone");
122	        }
123	        if (!missingFields.isEmpty()) {
124	            throw new InvalidOwnerFieldsException(missingFields);
125	        }
126	        // Normalize the telephone by stripping every non-digit character; it must
127	        // contain exactly 10 digits afterwards, otherwise the request is rejected.
128	        String normalizedTelephone = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
129	        if (normalizedTelephone.length() != 10) {
130	            throw new InvalidOwnerFieldsException(List.of("telephone"));
131	        }
132	        // Email is optional; when present it must be a syntactically valid address and is
133	        // stored lower-cased. An invalid address is rejected with a 400.
134	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
135	        // Reject the request if the normalized telephone is already used by any other owner.
136	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
137	            .map(Owner::getTelephone)
138	            .filter(existing -> existing != null)
139	            .map(existing -> existing.replaceAll("\\D", ""))
140	            .anyMatch(normalizedTelephone::equals);
141	        if (telephoneInUse) {
142	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
143	        }
144	        HttpHeaders headers = new HttpHeaders();
145	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
146	        owner.setTelephone(normalizedTelephone);
147	        owner.setEmail(normalizedEmail);
148	        // When no registration date is supplied, default it to the server's current date.
149	        if (owner.getRegistrationDate() == null) {
150	            owner.setRegistrationDate(LocalDate.now());
151	        }
152	        this.clinicService.saveOwner(owner);
153	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
154	        headers.setLocation(UriComponentsBuilder.newInstance()
155	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
156	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
162	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
163	        if (currentOwner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        currentOwner.setAddress(ownerFieldsDto.getAddress());
167	        currentOwner.setCity(ownerFieldsDto.getCity());
168	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
169	        currentOwner.setLastName(ownerFieldsDto.getLastName());
170	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
171	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
172	        this.clinicService.saveOwner(currentOwner);
173	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
174	    }
175	
176	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
177	    @Transactional
178	    @Override
179	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        this.clinicService.deleteOwner(owner);
185	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
186	    }
187	
188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
191	        Owner owner = this.clinicService.findOwnerById(ownerId);
192	        if (owner == null) {
193	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	        }
195	        HttpHeaders headers = new HttpHeaders();
196	        Pet pet = petMapper.toPet(petFieldsDto);
197	        owner.setId(ownerId);
198	        pet.setOwner(owner);
199	        pet.getType().setName(null);
200	        this.clinicService.savePet(pet);
201	        PetDto petDto = petMapper.toPetDto(pet);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
203	            .buildAndExpand(pet.getId()).toUri());
204	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner != null) {
212	            Pet currentPet = this.clinicService.findPetById(petId);
213	            if (currentPet != null) {
214	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
215	                currentPet.setName(petFieldsDto.getName());
216	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
217	                this.clinicService.savePet(currentPet);
218	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
227	        HttpHeaders headers = new HttpHeaders();
228	        Visit visit = visitMapper.toVisit(visitFieldsDto);
229	        Pet pet = new Pet();
230	        pet.setId(petId);
231	        visit.setPet(pet);
232	        this.clinicService.saveVisit(visit);
233	        VisitDto visitDto = visitMapper.toVisitDto(visit);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
235	            .buildAndExpand(visit.getId()).toUri());
236	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
237	    }
238	
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
243	        Owner owner = this.clinicService.findOwnerById(ownerId);
244	        if (owner != null) {
245	            Pet pet = owner.getPet(petId);
246	            if (pet != null) {
247	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
248	            }
249	        }
250	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	    }
252	
253	    private static boolean isBlank(String value) {
254	        return value == null || value.trim().isEmpty();
255	    }
256	
257	    /**
258	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
259	     * and a domain with at least one dot-separated label, none of which contain whitespace or
260	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
261	     */
262	    private static final Pattern EMAIL_PATTERN =
263	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
264	
265	    /**
266	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
267	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
268	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
269	     * 400. A valid address is returned lower-cased.
270	     */
271	    private static String normalizeEmail(String email) {
272	        if (email == null || email.isEmpty()) {
273	            return null;
274	        }
275	        String trimmed = email.trim();
276	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
277	            throw new InvalidOwnerFieldsException(List.of("email"));
278	        }
279	        return trimmed.toLowerCase();
280	    }
281	}
